class Solution {
public:
    int maxNonDecreasingLength(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        int dp1 = 1, dp2 = 1, ans = 1;
        for (int i = 1; i < n; ++i) {
            int new1 = 1, new2 = 1;
            if (nums1[i] >= nums1[i - 1]) new1 = max(new1, dp1 + 1);
            if (nums1[i] >= nums2[i - 1]) new1 = max(new1, dp2 + 1);
            if (nums2[i] >= nums1[i - 1]) new2 = max(new2, dp1 + 1);
            if (nums2[i] >= nums2[i - 1]) new2 = max(new2, dp2 + 1);
            dp1 = new1;
            dp2 = new2;
            ans = max({ans, dp1, dp2});
        }
        return ans;
    }
};

class Solution {
    public int maxNonDecreasingLength(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int dp1 = 1, dp2 = 1, ans = 1;
        for (int i = 1; i < n; i++) {
            int new1 = 1, new2 = 1;
            if (nums1[i] >= nums1[i - 1]) new1 = Math.max(new1, dp1 + 1);
            if (nums1[i] >= nums2[i - 1]) new1 = Math.max(new1, dp2 + 1);
            if (nums2[i] >= nums1[i - 1]) new2 = Math.max(new2, dp1 + 1);
            if (nums2[i] >= nums2[i - 1]) new2 = Math.max(new2, dp2 + 1);
            dp1 = new1;
            dp2 = new2;
            ans = Math.max(ans, Math.max(dp1, dp2));
        }
        return ans;
    }
}

